"""Indexed binary min-heap with O(log n) decrease-key.

The piece heapq is missing: items are keyed by a hashable id, and the
heap maintains an internal id -> position map so that the priority of
any contained id can be updated in place.
"""


class IndexedHeap:
    """Binary min-heap keyed by item id.

    - push(id, priority): add id with given priority (id must be new)
    - pop(): remove and return (id, smallest_priority)
    - decrease_key(id, new_priority): tighten an entry in O(log n)
    - contains(id) / __contains__: membership check in O(1)
    - peek(): return (id, min priority) without removing
    """

    def __init__(self, pairs=None):
        self._prio = []          # priorities, heap-ordered
        self._ids = []           # ids parallel to _prio
        self._pos = {}           # id -> index into _prio/_ids
        if pairs:
            for i, p in pairs:
                self.push(i, p)

    # -- internal helpers -------------------------------------------------

    def _swap(self, i, j):
        self._pos[self._ids[i]] = j
        self._pos[self._ids[j]] = i
        self._ids[i], self._ids[j] = self._ids[j], self._ids[i]
        self._prio[i], self._prio[j] = self._prio[j], self._prio[i]

    def _sift_up(self, i):
        while i > 0:
            parent = (i - 1) // 2
            if self._prio[i] < self._prio[parent]:
                self._swap(i, parent)
                i = parent
            else:
                break

    def _sift_down(self, i):
        n = len(self._prio)
        while True:
            left, right, smallest = 2 * i + 1, 2 * i + 2, i
            if left < n and self._prio[left] < self._prio[smallest]:
                smallest = left
            if right < n and self._prio[right] < self._prio[smallest]:
                smallest = right
            if smallest == i:
                break
            self._swap(i, smallest)
            i = smallest

    # -- public API --------------------------------------------------------

    def push(self, item_id, priority):
        if item_id in self._pos:
            raise KeyError(f"id already in heap: {item_id!r}")
        self._prio.append(priority)
        self._ids.append(item_id)
        idx = len(self._prio) - 1
        self._pos[item_id] = idx
        self._sift_up(idx)

    def pop(self):
        if not self._prio:
            raise IndexError("pop from empty heap")
        root_id, root_prio = self._ids[0], self._prio[0]
        last = len(self._prio) - 1
        del self._pos[root_id]
        if last == 0:
            self._prio.pop()
            self._ids.pop()
        else:
            self._ids[0] = self._ids[last]
            self._prio[0] = self._prio[last]
            self._pos[self._ids[0]] = 0
            self._prio.pop()
            self._ids.pop()
            self._sift_down(0)
        return root_id, root_prio

    def decrease_key(self, item_id, new_priority):
        if item_id not in self._pos:
            raise KeyError(f"id not in heap: {item_id!r}")
        i = self._pos[item_id]
        if new_priority > self._prio[i]:
            raise ValueError(
                f"new priority {new_priority!r} is larger than "
                f"current {self._prio[i]!r} for id {item_id!r}"
            )
        self._prio[i] = new_priority
        self._sift_up(i)

    def contains(self, item_id):
        return item_id in self._pos

    def __contains__(self, item_id):
        return item_id in self._pos

    def peek(self):
        if not self._prio:
            raise IndexError("peek at empty heap")
        return self._ids[0], self._prio[0]

    def get(self, item_id):
        try:
            return self._prio[self._pos[item_id]]
        except KeyError:
            raise KeyError(f"id not in heap: {item_id!r}") from None

    def __len__(self):
        return len(self._prio)

